$f=json_decode(file_get_contents('/gsm-private/fixtures.json'),true);$root=get_current_user_id();$checks=[];$tokens=[];$suffix=bin2hex(random_bytes(3));$roots=[];
$check=static function($ok,$name)use(&$checks):void{if(!$ok){throw new RuntimeException('FAIL: '.$name);} $checks[]=$name;};
$run=static function($job)use(&$tokens):array{$tokens[]=$job['token'];foreach($job['ids'] as $id){if($id!==999999999&&!str_starts_with((string)get_post_field('post_title',$id,'raw'),'QA052 ')){throw new RuntimeException('Nonfixture active task');}}for($i=0;$i<205&&$job['stage']==='running';++$i){$job=BulkProducts::step($job['token']);}if($job['stage']!=='done'){throw new RuntimeException('Job did not finish');}return $job;};
