$make=static function(string $label,int $brand=0)use($suffix,&$roots):WC_Product{$p=new WC_Product_Simple();$p->set_name('QA052 '.$label.' '.$suffix);$p->set_description('Shared description '.$suffix);$p->set_regular_price('40');$p->set_status('draft');$p->update_meta_data('_gsm_brand_id',$brand);$p->update_meta_data('_gsm_kind',$brand?'edition':'base');$p->save();$roots[]=$p->get_id();return $p;};
