$vbase=new WC_Product_Variable();$vbase->set_name('QA052 variable '.$suffix);$attr=new WC_Product_Attribute();$attr->set_name('Size');$attr->set_options(['Small','Large']);$attr->set_visible(true);$attr->set_variation(true);$vbase->set_attributes([$attr]);$vbase->set_status('draft');$vbase->update_meta_data('_gsm_kind','base');$vbase->update_meta_data('_gsm_brand_id',0);$vbase->save();$roots[]=$vbase->get_id();
foreach(['Small','Large'] as $i=>$size){$v=new WC_Product_Variation();$v->set_parent_id($vbase->get_id());$v->set_attributes(['size'=>$size]);$v->set_regular_price((string)(50+$i*10));$v->set_status('publish');$v->update_meta_data('_gsm_brand_id',0);$v->save();}WC_Product_Variable::sync($vbase->get_id());$vbase=wc_get_product($vbase->get_id());
