$paused=BulkProducts::control($job['token'],'pause');$idle=BulkProducts::step($job['token']);$check($paused['stage']==='paused'&&count($idle['results'])===0,'Paused jobs perform no writes');
$job=BulkProducts::control($job['token'],'resume');$job=$run($job);$counts=BulkProducts::summary($job);
$check($counts===['success'=>1,'skipped'=>2,'failed'=>1],'Mixed batch reports created, existing/nonpublic skipped and missing failed');
$new=wc_get_product(ProductVersions::edition($base->get_id(),11));$roots[]=$new->get_id();$check($new->get_status()==='draft'&&$new->get_meta('_gsm_overrides')===[]&&$new->get_regular_price()==='40'&&$new->get_description()===$base->get_description(),'New brand version is a draft with empty overrides and inherited values');
$check(serialize(wc_get_product($old->get_id())->get_data())===$snapshot,'Existing independent title, price, state and metadata remain byte-for-byte unchanged');
$complete=BulkProducts::step($job['token']);$check($complete['results']===$job['results'],'Replayed completed steps are idempotent');
$duplicate=$run(BulkProducts::start(BulkProducts::prepare('gsm_add_brand',[$base->get_id()])['token'],11));$check(BulkProducts::summary($duplicate)['skipped']===1&&ProductVersions::edition($base->get_id(),11)===$new->get_id(),'Repeated add skips the existing version without duplication');
$fail=true;$hook=static function($p)use(&$fail){if($fail&&$p->is_type('variation')&&(int)$p->get_meta('_gsm_brand_id')===12){$fail=false;throw new RuntimeException('Synthetic child failure');}};add_action('woocommerce_after_product_object_save',$hook,200);
$failed=$run(BulkProducts::start(BulkProducts::prepare('gsm_add_brand',[$vbase->get_id()])['token'],12));remove_action('woocommerce_after_product_object_save',$hook,200);
$check(BulkProducts::summary($failed)['failed']===1&&ProductVersions::edition($vbase->get_id(),12)===0,'A child-write failure reports failure and removes only the new partial product');
$job=$run(BulkProducts::control($failed['token'],'retry'));$var=wc_get_product(ProductVersions::edition($vbase->get_id(),12));$roots[]=$var->get_id();
$check(BulkProducts::summary($job)['success']===1&&count($var->get_children())===2&&!$var->get_meta('_gsm_build_state'),'Retry creates a complete inherited variable version with both children');
$check($var->get_status()==='draft'&&array_map(static fn($id)=>wc_get_product($id)->get_attributes(),$var->get_children())===array_map(static fn($id)=>wc_get_product($id)->get_attributes(),$vbase->get_children()),'Variable brand draft retains public specifications');
$var_id=$var->get_id();$var->delete(false);$trashed=$run(BulkProducts::start(BulkProducts::prepare('gsm_add_brand',[$vbase->get_id()])['token'],12));$check(BulkProducts::summary($trashed)['skipped']===1&&get_post_status($var_id)==='trash','Trashed associated versions are preserved and never silently duplicated');
$publish=BulkProducts::prepare('gsm_publish',[$new->get_id(),$old->get_id(),$base->get_id()]);$publish=$run(BulkProducts::start($publish['token']));
$check(BulkProducts::summary($publish)===['success'=>1,'skipped'=>2,'failed'=>0]&&get_post_status($new->get_id())==='publish','Bulk publish changes only selected sale versions and skips public/already published');
$check(serialize(wc_get_product($old->get_id())->get_data())===$snapshot,'Status batch does not write an already-published overridden version');
$draft=$run(BulkProducts::start(BulkProducts::prepare('gsm_draft',[$new->get_id()])['token']));$check(get_post_status($new->get_id())==='draft'&&BulkProducts::summary($draft)['success']===1,'Bulk draft changes the selected brand version only');
$conflict=BulkProducts::prepare('gsm_publish',[$new->get_id()]);$changed=wc_get_product($new->get_id());$changed->set_status('private');$changed->save();$conflict=$run(BulkProducts::start($conflict['token']));$check($conflict['results'][$new->get_id()]['code']==='conflict'&&get_post_status($new->get_id())==='private','Changed publication state after selection is skipped without overwriting');
update_post_meta($new->get_id(),'_gsm_build_state','creating');$incomplete=$run(BulkProducts::start(BulkProducts::prepare('gsm_add_brand',[$base->get_id()])['token'],11));$check(BulkProducts::summary($incomplete)['failed']===1,'Incomplete existing drafts are reported instead of duplicated');
$repair=wc_get_product($new->get_id());$repair->save();$retry=$run(BulkProducts::control($incomplete['token'],'retry'));$check(BulkProducts::summary($retry)['skipped']===1&&!get_post_meta($new->get_id(),'_gsm_build_state',true),'Explicit draft update completes an interrupted version; retry then safely skips it');
$limited=false;try{BulkProducts::prepare('gsm_add_brand',range(1,201));}catch(Throwable $e){$limited=true;}$check($limited,'More than 200 distinct selections are rejected before execution');
wp_set_current_user((int)$f['staff']);Stores::within(6,static function()use($root,$own,$old,$check,$run,&$tokens):void{
 $denied=false;try{BulkProducts::prepare('gsm_add_brand',[$own->get_id()]);}catch(Throwable $e){$denied=true;}$check($denied,'Employee cannot create brand associations');
 $job=BulkProducts::prepare('gsm_publish',[$own->get_id(),$old->get_id()]);$tokens[]=$job['token'];$job=$run(BulkProducts::start($job['token']));$check(BulkProducts::summary($job)===['success'=>1,'skipped'=>0,'failed'=>1]&&get_post_status($own->get_id())==='publish','Employee can publish own A product and cannot change unauthorized E');
});wp_set_current_user($root);
$visible=BulkProducts::prepare('gsm_add_brand',[$base->get_id()]);$tokens[]=$visible['token'];wp_set_current_user((int)$f['staff']);$hidden=Stores::within(6,static function()use($visible){try{BulkProducts::get($visible['token']);return false;}catch(Throwable $e){return true;}});wp_set_current_user($root);$check($hidden,'Job identifiers cannot expose another user task');
// Leave unassociated public fixtures for real native UI/HTTP tests, all in private manifest.
